+const cost = s => Buffer.byteLength(frame(s), 'utf8');
+
+test('safe integer boundaries and full validation at zero budget', () => {
+  const max = Number.MAX_SAFE_INTEGER;
+  assert.deepEqual(packContext([], max), { text: '', bytes: 0, included: [], omitted: [] });
+  assert.deepEqual(packContext([section('x', '', max)], max).included, ['x']);
+  for (const bad of [-1, 0.5, NaN, Infinity, max + 1, '1', null, undefined, 1n]) {
+    assert.throws(() => packContext([], bad), Error);
+    assert.throws(() => packContext([{ id: 'x', text: '', priority: bad, required: false }], 0), Error);
+  }
+  for (const bad of [null, {}, 'x', 1]) assert.throws(() => packContext(bad, 0), Error);
+  const invalid = [null, [], 1, {}, section(''), section('x', 1),
+    { id: 'x', text: '', priority: 0 }, section('x', '', 0, 1), section(1)];
+  for (const bad of invalid) {
+    assert.throws(() => packContext([section('valid'), bad], 0), Error);
+  }
+  for (const field of ['id', 'text', 'priority', 'required']) {
+    const bad = section('x');
+    delete bad[field];
+    assert.throws(() => packContext([bad], 0), Error);
+  }
+  assert.throws(() => packContext([section('x'), section('x')], 0), Error);
+  assert.throws(() => packContext(new Array(2), 0), Error);
+});
+
+test('required order, optional stable priority, skip and omission input order', () => {
+  const sections = [section('low', 'L', 0), section('r1', '', 0, true),
+    section('huge', 'x'.repeat(1000), 100), section('tie1', '', 3),
+    section('r2', '', 100, true), section('tie2', '', 3), section('medium', 'x'.repeat(1000), 2)];
+  const chosen = [sections[1], sections[4], sections[3], sections[5], sections[0]];
+  const text = chosen.map(frame).join('');
+  const budget = Buffer.byteLength(text);
+  assert.deepEqual(packContext(sections, budget), {
+    text, bytes: budget, included: chosen.map(s => s.id), omitted: ['huge', 'medium']
+  });
+  assert.deepEqual(packContext(sections, cost(sections[1]) + cost(sections[4])).omitted,
+    ['low', 'huge', 'tie1', 'tie2', 'medium']);
+  assert.throws(() => packContext(sections, cost(sections[1]) + cost(sections[4]) - 1), Error);
+});
+
+test('exact framing preserves unusual IDs, UTF-8 and whitespace without mutation', () => {
+  const sections = ['__proto__', 'A', 'a', ' ', '\n\u0000雪"\\', '\ud800'].map(id =>
+    Object.freeze({ ...section(id, ' \r\né😀\n '), ignored: true }));
+  Object.freeze(sections);
+  const text = sections.map(frame).join('');
+  const bytes = Buffer.byteLength(text);
+  assert.deepEqual(packContext(sections, bytes), {
+    text, bytes, included: sections.map(s => s.id), omitted: []
+  });
+  assert.deepEqual(packContext([sections[0]], cost(sections[0]) - 1), {
+    text: '', bytes: 0, included: [], omitted: ['__proto__']
+  });
+});
+
+test('CLI success, errors and import isolation', () => {
+  const dir = mkdtempSync(join(tmpdir(), 'context-packet-test-'));
+  const script = fileURLToPath(new URL('../context-packet.js', import.meta.url));
+  const run = args => spawnSync(process.execPath, [script, ...args], { encoding: 'utf8' });
+  const failure = result => {
+    assert.equal(result.error, undefined);
+    assert.equal(result.status, 2);
+    assert.equal(result.stdout, '');
+    assert.ok(result.stderr.length > 0);
+  };
+  try {
+    const file = join(dir, 'input.json');
+    const input = { sections: [section('雪', 'é', 0, true)], maxBytes: 100, extra: true };
+    writeFileSync(file, JSON.stringify(input));
+    const success = run([file]);
+    assert.equal(success.status, 0);
+    assert.equal(success.stderr, '');
+    assert.equal(success.stdout, JSON.stringify(packContext(input.sections, input.maxBytes)) + '\n');
+    failure(run([]));
+    failure(run([file, file]));
+    failure(run([join(dir, 'missing.json')]));
+    for (const content of ['{', 'null', '[]', '{}', JSON.stringify({ ...input, maxBytes: 0 }),
+      JSON.stringify({ sections: [section('x', '', Number.MAX_SAFE_INTEGER + 1)], maxBytes: 0 })]) {
+      writeFileSync(file, content);
+      failure(run([file]));
+    }
+    const imported = spawnSync(process.execPath,
+      ['--input-type=module', '-e', `import ${JSON.stringify(new URL('../context-packet.js', import.meta.url).href)}`],
+      { encoding: 'utf8' });
+    assert.equal(imported.status, 0);
+    assert.equal(imported.stdout, '');
+    assert.equal(imported.stderr, '');
+  } finally {
+    rmSync(dir, { recursive: true, force: true });
+  }
+});

